package solution

import (
	"strings"
	"testing"
)

func TestCountNonEmpty(t *testing.T) {
	cases := []struct {
		in   string
		want int
	}{
		{"a\nb\nc", 3},
		{"a\n\nb\n", 2},
		{"", 0},
		{"\n\n", 0},
	}
	for _, c := range cases {
		got, err := CountNonEmpty(strings.NewReader(c.in))
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got != c.want {
			t.Errorf("CountNonEmpty(%q)=%d want %d", c.in, got, c.want)
		}
	}
}

